#include <vector>
#include <queue>
#include <unordered_set>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<int> findAllPeople(int n, std::vector<std::vector<int>>& meetings, int firstPerson) {
        std::unordered_set<int> known = {0, firstPerson};
        std::sort(meetings.begin(), meetings.end(), [](const auto& a, const auto& b) {
            return a[2] < b[2];
        });

        int i = 0, mLen = meetings.size();
        while (i < mLen) {
            int t = meetings[i][2];
            std::unordered_map<int, std::vector<int>> adj;
            std::unordered_set<int> participants;

            while (i < mLen && meetings[i][2] == t) {
                int u = meetings[i][0], v = meetings[i][1];
                adj[u].push_back(v);
                adj[v].push_back(u);
                participants.insert(u);
                participants.insert(v);
                i++;
            }

            std::queue<int> q;
            std::unordered_set<int> visited;
            for (int p : participants) {
                if (known.count(p)) {
                    q.push(p);
                    visited.insert(p);
                }
            }

            while (!q.empty()) {
                int curr = q.front();
                q.pop();
                for (int neighbor : adj[curr]) {
                    if (!visited.count(neighbor)) {
                        visited.insert(neighbor);
                        known.insert(neighbor);
                        q.push(neighbor);
                    }
                }
            }
        }

        std::vector<int> ans(known.begin(), known.end());
        std::sort(ans.begin(), ans.end());
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<Integer> findAllPeople(int n, int[][] meetings, int firstPerson) {
        Set<Integer> known = new HashSet<>();
        known.add(0);
        known.add(firstPerson);

        Arrays.sort(meetings, Comparator.comparingInt(a -> a[2]));

        int i = 0, mLen = meetings.length;
        while (i < mLen) {
            int t = meetings[i][2];
            Map<Integer, List<Integer>> adj = new HashMap<>();
            Set<Integer> participants = new HashSet<>();

            while (i < mLen && meetings[i][2] == t) {
                int u = meetings[i][0], v = meetings[i][1];
                adj.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
                adj.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
                participants.add(u);
                participants.add(v);
                i++;
            }

            Deque<Integer> q = new ArrayDeque<>();
            Set<Integer> visited = new HashSet<>();
            for (int p : participants) {
                if (known.contains(p)) {
                    q.offer(p);
                    visited.add(p);
                }
            }

            while (!q.isEmpty()) {
                int curr = q.poll();
                if (!adj.containsKey(curr)) continue;
                for (int neighbor : adj.get(curr)) {
                    if (!visited.contains(neighbor)) {
                        visited.add(neighbor);
                        known.add(neighbor);
                        q.offer(neighbor);
                    }
                }
            }
        }

        List<Integer> ans = new ArrayList<>(known);
        Collections.sort(ans);
        return ans;
    }
}

